import {warmupMinutes} from './warmup.js';
import {equipmentChoices,equipmentKeys} from './equipment.js';
import { makeDemoWorkspace } from './demo.js';
import {brandsFor,machineSearchText} from './machines.js';
import { openExerciseEditor } from './exercise-editor.js';
import {uuid,gear,available,alternatives,makeDraft,canApprove,estimateSeconds,validateSession} from './engine.js';
import { authClient } from './auth-client.js';
import { renderLogin, requestProfile } from './auth-ui.js';
async function start(){
if(location.pathname.replace(/\/$/,'')==='/intake'){await (await import('./intake.js')).startIntake();return;}
if(location.pathname.replace(/\/$/,'')==='/client'){await (await import('./client.js')).startClient();return;}
const demo=location.pathname.replace(/\/$/,'')==='/demo';
let profile;
try { profile=demo?{user:{name:'Demonstration'},verified:true,owner:true}:await requestProfile(); } catch { document.querySelector('#app').innerHTML='<main class="error"><h1>Login er midlertidigt utilgængeligt.</h1><a href="/">Prøv igen</a></main>';return; }
if(profile.user&&profile.verified&&!profile.owner){location.replace('/client');return;}
if(!profile.user||!profile.verified){renderLogin(profile);return;}
const app=document.querySelector('#app');
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',people:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M16 4a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 4v3"/>',form:'<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6M9 12h6M9 16h4"/>',exercise:'<path d="M3 8v8m4-11v14m10-14v14m4-11v8M7 12h10"/>',place:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',book:'<path d="M12 5v16M3 3c4-1 7 0 9 2 2-2 5-3 9-2v16c-4-1-7 0-9 2-2-2-5-3-9-2Z"/>',settings:'<path d="m9 3-1 3-3 1 1 3-2 2 2 2-1 3 3 1 1 3h6l1-3 3-1-1-3 2-2-2-2 1-3-3-1-1-3Z"/><circle cx="12" cy="12" r="3"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10" cy="10" r="6.5"/><path d="m15 15 6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',chevron:'<path d="m9 5 7 7-7 7"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',play:'<path d="m9 5 12 7-12 7Z"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',swap:'<path d="M3 7h17l-4-4M21 17H4l4 4M20 7l-4 4M4 17l4-4"/>',shield:'<path d="m12 2 8 4v6c0 6-8 10-8 10S4 18 4 12V6Z"/><path d="m8 12 3 3 5-6"/>',logout:'<path d="M9 4H3v16h6M9 12h12l-4-4m4 4-4 4"/>',dots:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l1 1m12 12 1 1M5 19l1-1M18 6l1-1"/>'})[name]||''}</svg>`;
const knowledge = await fetch('/api/knowledge').then(async response=>{
 if(!response.ok)throw new Error('Knowledge unavailable');
 const content=await response.json();
 if(!['exercises','sources','questions','rules'].every(key=>Array.isArray(content[key])&&content[key].length))throw new Error('Knowledge incomplete');
 return content;
}).catch(()=>{
 app.innerHTML='<main class="error"><h1>Vidensbanken er midlertidigt utilgængelig.</h1><p>Forbindelsen til databasen kunne ikke oprettes. Dine oplysninger ændres ikke.</p><a href="/">Prøv at indlæse siden igen</a></main>';
 throw new Error('Knowledge load failed');
});
const {exercises,sources,questions}=knowledge;
if(!demo){try{const r=await fetch('/api/exercises',{cache:'no-store'});if(r.ok){const b=await r.json();exercises.splice(0,exercises.length,...b.exercises);}}catch{ /* Existing read-only knowledge remains available. */ }}
const defaultPlaces=[{id:'gym',name:'Mit fitnesscenter',type:'Center',note:'Vælg det udstyr, som faktisk er tilgængeligt. Der er ikke valgt noget på forhånd.',inventory:[]},{id:'home',name:'Hjemme',type:'Hjemme',note:'Registrer udstyr, plads og sikre fæster, før du laver et forløb.',inventory:[]}];
function initial(){return {programs:[],places:structuredClone(defaultPlaces),answers:{},workouts:{},version:1};}
let workspace;
try{if(demo){workspace={data:makeDemoWorkspace(exercises),revision:0};}else{const response=await fetch('/api/workspace',{cache:'no-store'});if(!response.ok)throw Error();workspace=await response.json();}}catch{app.innerHTML='<main class="error"><h1>Arbejdsrummet kunne ikke hentes.</h1><a href="/">Prøv igen</a></main>';return;}
let state=workspace.data||initial();
let current=state.programs[0]?.id;let view='overview',step=0,selectedPlace=state.places[0].id;let exerciseFilter='',exerciseSearch='',exerciseGear='',exerciseBrand='',warmupOnly=false,week=1,client=false,workout=null;let toastTimer;
let clientRows=null,clientsError='',deleting=false;
let invitationRows=null,invitationError='';let intakeRows=null,intakeError='';
let revision=workspace.revision,dirty=false,saving=false,saveTimer,savePaused=false,saveMessage=demo?'Demo · Nulstilles ved genindlæsning':'Gemt privat i Neon';
const setSaveMessage=(message,error=false)=>{saveMessage=message;const el=document.querySelector('#save-state');if(el){el.textContent=message;el.classList.toggle('error',error);}};
async function flush(){
 if(demo)return;
 if(saving||!dirty||savePaused)return;
 saving=true;dirty=false;setSaveMessage('Gemmer…');
 try{
  const response=await fetch('/api/workspace',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({data:structuredClone(state),revision})});
  const body=await response.json();
  if(!response.ok){savePaused=true;throw Error(body.error||'Ændringerne kunne ikke gemmes.');}
  revision=body.revision;setSaveMessage('Gemt privat i Neon');
 }catch(error){dirty=true;savePaused=true;setSaveMessage('Ikke gemt · Hold siden åben',true);toast(error.message||'Forbindelsen blev afbrudt. Hold siden åben.');}
 finally{saving=false;if(dirty&&!savePaused)void flush();}
}
const save=()=>{if(demo){setSaveMessage('Demo · Ændringer gemmes kun i denne åbne side');return;}dirty=true;setSaveMessage('Ændringer afventer lagring');clearTimeout(saveTimer);saveTimer=setTimeout(flush,500);};
window.addEventListener('beforeunload',event=>{if(dirty||saving||deleting){event.preventDefault();event.returnValue='';}});
const toast=text=>{const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4500);};
const getP=()=>state.programs.find(p=>p.id===current);
const nav=[['overview','Overblik','grid'],['programs','Forløb','people'],['clients','Klienter','people'],['invitations','Invitationer','shield'],['intakes','Skemabesvarelser','form'],['questionnaire','Spørgeskema','form'],['exercises','Øvelsesbank','exercise'],['places','Træningssteder','place'],['knowledge','Vidensbank','book']];
function go(v){if(deleting)return;view=v;client=false;workout=null;location.hash=v;render();window.scrollTo({top:0,behavior:'instant'});if(v==='clients')void loadClients();if(v==='invitations')void loadInvitations();if(v==='intakes')void loadIntakes();}
function render(){
 document.title='PTDahl · '+(nav.find(n=>n[0]===view)?.[1]||'Dit forløb');
 app.innerHTML=`<div class="layout"><aside class="sidebar"><a href="#overview" class="brand" aria-label="PTDahl overblik"><span class="brand-mark">${icon('exercise',23)}</span><span>PT<span class="brand-serif">Dahl</span><small>PERSONLIG TRÆNING</small></span></a><div class="workspace-label">${demo?'DEMONSTRATION <span>DEMO</span>':'DIT PRIVATE ARBEJDSRUM <span>ADMIN</span>'}</div><nav aria-label="Hovedmenu">${nav.map(([id,label,ic])=>`<button class="nav-item ${view===id?'active':''}" data-nav="${id}" aria-label="${label}">${icon(ic)}<span>${label}</span>${id==='programs'?`<span class="nav-count">${state.programs.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="crafted"><span class="gold-dot"></span> TRÆNING MED OMTANKE<p>En plan. Et menneske.<br>Et skridt ad gangen.</p></div><button class="nav-item ${view==='settings'?'active':''}" data-nav="settings">${icon('settings')} Opsætning</button><div class="profile"><div class="avatar gold">TD</div><div><strong>${demo?'Fiktiv træner':'Thomas Dahl'}</strong><small>${demo?'Demonstration':'Ejer · administrator'}</small></div><button class="signout-btn" data-action="signout" aria-label="Log ud">${icon('logout',16)}</button></div></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">PTDahl <span>/</span> ${esc(client?'Brugervisning':nav.find(n=>n[0]===view)?.[1]||'Opsætning')}</div><div class="top-actions"><span class="demo-pill"><i></i> ${demo?'Demonstration':'Privat arbejdsrum'}</span><button class="icon-btn" title="Om PTDahl" aria-label="Om PTDahl" data-nav="settings">${icon('shield')}</button><div class="avatar small">TD</div></div></header><div class="demo-banner real-banner"><span>${demo?'DEMO · Kun fiktive data. Intet gemmes i det rigtige arbejdsrum.':'Kun din bekræftede konto har adgang.'}</span><span id="save-state" class="save-indicator">${esc(saveMessage)}</span>${demo?'<a href="/demo">Nulstil demo</a><a href="/">Til login</a>':'<a href="/demo" target="_blank" rel="noopener">Åbn demo</a><button data-action="retry-save">Gem igen</button>'}</div><main id="main" tabindex="-1">${client?clientView():({overview:overview,programs:programsView,questionnaire:questionnaireView,clients:clientsView,invitations:invitationsView,intakes:intakesView,exercises:exerciseView,places:placesView,knowledge:knowledgeView,settings:settingsView}[view]||overview)()}</main><footer>PTDahl <span>PERSONLIG TRÆNING. MED OMTANKE.</span><span>Design og funktioner · version 0.9</span></footer></div></div>`;
 bind();
}
async function intakeApi(method,body){const r=await fetch('/api/intake-invitations',{method,cache:'no-store',headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})}),b=await r.json();if(!r.ok)throw Error(b.error||'Skemaet kunne ikke behandles.');return b;}
async function freshWorkspace(){if(demo)return true;if(dirty||saving||savePaused){toast('Gem dine ændringer først. Genindlæs ved en konflikt.');return false;}const r=await fetch('/api/workspace',{cache:'no-store'});if(!r.ok)throw Error('Arbejdsrummet kunne ikke hentes.');const w=await r.json();if(w.data){state=w.data;revision=w.revision;current=state.programs.some(p=>p.id===current)?current:state.programs[0]?.id;}return true;}
async function loadIntakes(){intakeRows=null;intakeError='';if(view==='intakes')render();try{if(demo){intakeRows=[];}else{intakeRows=(await intakeApi('GET')).requests;if(!dirty&&!saving&&!savePaused)await freshWorkspace();}}catch(e){intakeError=e.message;}if(view==='intakes')render();}
function intakesView(){return `${heading('FØRST SVAR. DEREFTER DIN VURDERING.','Personligt fra begyndelsen.','Inviter klienten til selv at udfylde sit spørgeskema.',`<button class="btn primary" data-action="new-intake">Inviter til spørgeskema</button>`)}<section class="panel settings-panel"><h2>Du har stadig sidste ord.</h2><p>Klienten opretter en konto og bekræfter sin mail. Svar kan gemmes undervejs. Efter indsendelse ligger svar og et eventuelt programudkast her til din gennemgang. Intet program deles automatisk.</p><p>Gennemgå svarene, tilpas kladden og godkend forløbet. Vælg derefter Inviter / del version for at give klienten adgang. Skemalinket gælder i 14 dage. Du kopierer og sender linket selv; automatisk mail er endnu ikke tilsluttet.</p><button class="btn secondary" data-action="refresh-intakes">Hent nye svar</button></section><section class="panel client-register">${intakeError?`<p role="alert">${esc(intakeError)}</p>`:!intakeRows?'<p role="status">Henter skemabesvarelser…</p>':intakeRows.map(i=>`<article class="client-record"><div class="grow"><h3>${esc(i.name)}</h3><p>${esc(i.email)}</p><span class="status ${i.status==='submitted'?'green':'amber'}">${i.status==='submitted'?'Besvaret · til din gennemgang':new Date(i.expires_at)<new Date()?'Link udløbet':'Afventer svar'}</span>${i.draft_error?`<p class="help">${esc(i.draft_error)}</p>`:''}<p class="help">${i.submitted_at?'Indsendt '+new Date(i.submitted_at).toLocaleDateString('da-DK'):'Link udløber '+new Date(i.expires_at).toLocaleDateString('da-DK')}</p></div><div class="intake-actions"><button class="btn secondary" data-intake-answers="${esc(i.id)}">Se svar</button>${i.program_id?`<button class="btn primary" data-intake-program="${esc(i.id)}">Gennemgå forløb</button>`:i.status==='submitted'?`<button class="btn primary" data-intake-program="${esc(i.id)}">Åbn svar i spørgeskema</button>`:''}<button class="text-btn" data-intake-revoke="${esc(i.id)}">Fjern skemainvitation</button></div></article>`).join('')||'<p>Ingen skemainvitationer endnu.</p>'}</section>`;}
function createIntakeInvitation(){if(demo){modal('Skemainvitation i demoen','<p>I det rigtige arbejdsrum opretter du her et personligt link. Klienten udfylder skemaet, og du gennemgår svar og kladde før deling. Demoen opretter ingen rigtige invitationer.</p>');return;}if(dirty||saving||savePaused){toast('Vent til arbejdsrummet er gemt før invitation.');return;}modal('Inviter til spørgeskema',`<p>Klienten skal oprette sig med denne mailadresse og bekræfte den. Et besvaret skema giver ingen programadgang.</p><form id="intake-invite-form"><div class="field"><label>Klientens navn<input name="name" required maxlength="100"></label></div><div class="field"><label>Klientens mailadresse<input type="email" name="email" required maxlength="254"></label></div><p id="intake-invite-error" role="alert"></p><button class="btn primary full" type="submit">Opret personligt skemalink</button></form>`);document.querySelector('#intake-invite-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const r=await intakeApi('POST',Object.fromEntries(new FormData(e.target)));await freshWorkspace();modal('Skemainvitationen er klar',`<p>Til <strong>${esc(r.email)}</strong> · gyldigt i 14 dage.</p><p>Der er ikke sendt en mail. Kopiér linket og send det til klienten. Personen får først programadgang efter din godkendelse og deling.</p><div class="field"><label>Personligt skemalink<input readonly id="intake-copy-link" value="${esc(r.url)}"></label></div><button class="btn primary full" id="intake-copy">Kopiér skemalink</button><p role="status" id="intake-copy-status"></p>`);document.querySelector('#intake-copy').onclick=async()=>{const input=document.querySelector('#intake-copy-link');input.select();try{await navigator.clipboard.writeText(input.value);document.querySelector('#intake-copy-status').textContent='Skemalinket er kopieret.';}catch{document.querySelector('#intake-copy-status').textContent='Linket er markeret. Brug Kopiér i din browser.';}};if(view==='intakes')void loadIntakes();}catch(error){document.querySelector('#intake-invite-error').textContent=error.message;button.disabled=false;}};}
function showIntakeAnswers(id){const i=intakeRows?.find(i=>i.id===id);if(!i)return;modal('Besvarelse · '+i.name,`<p>${esc(i.email)} · ${i.status==='submitted'?'Indsendt til gennemgang':'Ikke indsendt endnu'}</p><dl class="intake-answers">${questions.filter(q=>Object.hasOwn(i.answers||{},q.key)).map(q=>{const value=i.answers[q.key];return `<dt>${esc(q.label_da.split('?')[0])}</dt><dd>${esc(Array.isArray(value)?value.map(v=>q.key==='equipment'?gear[v]||v:v).join(' · '):typeof value==='boolean'?value?'Ja':'Nej':value||'Ikke oplyst')}</dd>`;}).join('')||'<p>Der er endnu ingen gemte svar.</p>'}</dl>`);}
async function openIntakeProgram(id){const i=intakeRows?.find(i=>i.id===id);if(!i)return;try{if(!await freshWorkspace())return;if(i.program_id){const p=state.programs.find(p=>p.id===i.program_id);if(!p){toast('Forløbet er fjernet. Besvarelsen kan stadig gennemgås.');return;}current=p.id;week=1;go('programs');showIntakeAnswers(id);return;}state.answers=structuredClone(i.answers);const place={id:uuid(),name:'Oplyst af '+i.name,type:'Klientens udstyr',inventory:[...(i.answers.equipment||[])]};state.places.push(place);selectedPlace=place.id;step=0;save();go('questionnaire');toast('Svarene er åbnet til din tilpasning. Intet er delt med klienten.');}catch(e){toast(e.message);}}
function revokeIntake(id){if(demo)return;modal('Fjern skemainvitation','<p>Skemalinket og gemte svar på invitationen slettes. Et allerede oprettet forløb og svarene i det bevares og kan slettes under Klienter.</p><p id="intake-remove-error" role="alert"></p><button class="btn danger" id="intake-remove">Fjern skemainvitation og skemasvar</button>');document.querySelector('#intake-remove').onclick=async e=>{e.target.disabled=true;try{await intakeApi('DELETE',{id});document.querySelector('#modal').close();await loadIntakes();}catch(error){document.querySelector('#intake-remove-error').textContent=error.message;e.target.disabled=false;}};}

async function invitationApi(method,body){const r=await fetch('/api/invitations',{method,cache:'no-store',headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const result=await r.json();if(!r.ok)throw Error(result.error||'Invitationen kunne ikke behandles.');return result;}
async function loadInvitations(){invitationRows=null;invitationError='';if(view==='invitations')render();try{invitationRows=demo?[]:(await invitationApi('GET')).invitations;}catch(e){invitationError=e.message;}if(view==='invitations')render();}
function invitationsView(){return `${heading('DEL KUN DET GODKENDTE','Adgang med omtanke.','Personlige invitationer og adgang til dine klienters forløb.',`<button class="btn secondary" data-action="refresh-invitations">Opdater oversigt</button>`)}<section class="panel settings-panel"><h2>Fra godkendelse til klientadgang</h2><p>Åbn et godkendt forløb og vælg “Inviter / del version”. Linket gælder i 7 dage og kan kun accepteres én gang, med klientens bekræftede mailadresse. Klienten opretter selv sin adgangskode.</p><p>Automatisk invitationsmail er endnu ikke tilsluttet. Du kopierer linket og sender det selv. Deling til en klient med aktiv adgang udgiver den nye godkendte version. Træningsregistrering starter på ny for den delte version.</p><button class="btn primary" data-nav="programs">Åbn forløb</button></section><section class="panel client-register">${invitationError?`<p role="alert">${esc(invitationError)}</p>`:!invitationRows?'<p role="status">Henter invitationer…</p>':invitationRows.map(i=>`<article class="client-record"><div class="grow"><h3>${esc(state.programs.find(p=>p.id===i.program_id)?.name||'Forløb')}</h3><p>${esc(i.email)}</p><span class="status ${i.accepted_at?'green':'amber'}">${i.accepted_at?'Aktiv klientadgang':new Date(i.expires_at)<new Date()?'Link udløbet':'Afventer accept'}</span><p class="help">${i.accepted_at?'Accepteret '+new Date(i.accepted_at).toLocaleDateString('da-DK'):'Link udløber '+new Date(i.expires_at).toLocaleDateString('da-DK')}</p></div><button class="btn danger-outline" data-revoke="${esc(i.id)}">Tilbagekald adgang</button></article>`).join('')||'<p>Ingen invitationer endnu. Opret et link fra et godkendt forløb.</p>'}</section>`;}
async function inviteClient(){if(demo){modal('Invitation i demoen','<p>I det rigtige arbejdsrum opretter du her et personligt link til det godkendte forløb. Klienten bekræfter sin mailadresse og opretter selv en adgangskode. Demoen opretter ingen rigtige invitationer.</p>');return;}if(dirty||saving||savePaused){toast('Vent til ændringerne er gemt før deling. Genindlæs ved en konflikt.');return;}const p=getP();if(p?.status!=='approved')return;modal('Del godkendt forløb',`<p>Forløbet deles med <strong>${esc(p.answers?.email||'Ingen mail registreret')}</strong>.</p><p>Klienten får adgang til version ${p.version}. Ved eksisterende adgang erstattes den tidligere delte version, og træningsregistrering starter på ny. Andre kladder og spørgeskemasvar deles ikke.</p><p>Der sendes ingen automatisk mail. Kopiér det personlige link efter oprettelsen, og send det til klienten.</p><p id="invite-error" role="alert"></p><button class="btn primary full" id="create-invite">Opret link / del version</button>`);document.querySelector('#create-invite').onclick=async e=>{e.target.disabled=true;try{const r=await invitationApi('POST',{program_id:p.id,revision});if(r.accepted){modal('Versionen er delt',`<p>${esc(r.email)} har allerede klientadgang. Den godkendte version er nu tilgængelig ved næste åbning af forløbet.</p>`);return;}modal('Dit personlige invitationslink',`<p>Til <strong>${esc(r.email)}</strong> · gyldigt i 7 dage.</p><p>Der er ikke sendt en mail. Send linket til klienten. Et nyt link til samme forløb erstatter det forrige.</p><div class="field"><label>Invitationslink<input id="invite-link" readonly value="${esc(r.url)}"></label></div><button class="btn primary full" id="copy-invite">Kopiér link</button><p id="copy-status" role="status"></p>`);document.querySelector('#copy-invite').onclick=async()=>{const input=document.querySelector('#invite-link');input.select();try{await navigator.clipboard.writeText(input.value);document.querySelector('#copy-status').textContent='Linket er kopieret. Du kan sende det til klienten.';}catch{document.querySelector('#copy-status').textContent='Linket er markeret. Brug Kopiér i din browser.';}};}catch(error){document.querySelector('#invite-error').textContent=error.message;e.target.disabled=false;}};}
function revokeInvitation(id){if(demo)return;modal('Tilbagekald klientadgang','<p>Invitationslink og adgang til dette forløb fjernes. Træningsregistreringerne for denne adgang slettes. Selve forløbet og klientkontoen bevares.</p><p id="revoke-error" role="alert"></p><button class="btn danger full" id="confirm-revoke">Tilbagekald adgang</button>');document.querySelector('#confirm-revoke').onclick=async e=>{e.target.disabled=true;try{await invitationApi('DELETE',{id});document.querySelector('#modal').close();await loadInvitations();toast('Klientadgangen er tilbagekaldt.');}catch(error){document.querySelector('#revoke-error').textContent=error.message;e.target.disabled=false;}};}
function addMachineReference(exercise){modal('Tilføj maskine til øvelsen',`<form id="machine-form"><p><strong>${esc(exercise.name_da)}</strong></p><p class="help">Registrer et konkret maskineksempel til denne grundøvelse. Instruktion og programhenvisninger ændres ikke. Brug kun generelle udstyrsoplysninger.</p><div class="field"><label>Mærke<input name="brand" required maxlength="150" placeholder="Fx Technogym"></label></div><div class="field"><label>Serie (valgfri)<input name="series" maxlength="150"></label></div><div class="field"><label>Model<input name="model" required maxlength="150"></label></div><div class="field"><label>Kildelink (valgfrit)<input name="url" type="url" placeholder="https://…" maxlength="500"></label></div><p id="machine-error" role="alert"></p><button class="btn primary full" type="submit">${demo?'Tilføj i denne demo':'Gem maskineksempel'}</button></form>`);document.querySelector('#machine-form').onsubmit=async event=>{event.preventDefault();const form=event.target,fields=Object.fromEntries(new FormData(form)),button=form.querySelector('[type=submit]');button.disabled=true;try{if(fields.url&&new URL(fields.url).protocol!=='https:')throw Error('Brug et https kildelink.');if(demo){exercise.machine_references=[...(exercise.machine_references||[]),{...fields,match_status:'coach_recorded_verify_local_setup'}];}else{const r=await fetch('/api/exercises',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...fields,action:'add-machine-reference',id:exercise.id,revision:exercise.revision})}),result=await r.json();if(!r.ok)throw Error(result.error);Object.assign(exercise,result.exercise);}document.querySelector('#modal').close();render();toast(demo?'Maskineksemplet er tilføjet i denne demo.':'Maskineksemplet er gemt på øvelsen.');}catch(error){document.querySelector('#machine-error').textContent=error.message||'Maskinen kunne ikke tilføjes.';button.disabled=false;}};}
function editExercise(exercise){openExerciseEditor({exercise,sources,demo,modal,esc,onSaved:e=>{exercises.push(e);exerciseSearch=e.name_da;exerciseFilter='';exerciseGear='';exerciseBrand='';warmupOnly=false;go('exercises');toast(demo?'Øvelsen er oprettet i denne demo.':'Øvelsen er gemt i Neon og klar til din programgennemgang.');}});}
function heading(kicker,title,desc,action=''){return `<section class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${desc}</p></div>${action}</section>`;}
function pill(status){return `<span class="status ${status==='approved'?'green':'amber'}"><i></i>${status==='approved'?'Godkendt':'Afventer din gennemgang'}</span>`;}
function initials(s){return s.split(' ').map(x=>x[0]).slice(0,2).join('');}
function programRows(){if(!state.programs.length)return '<div class="empty panel"><p>Dit arbejdsrum er klar. Opret dit første forløb via spørgeskemaet.</p><button class="btn primary" data-nav="questionnaire">Opret første forløb</button></div>';return state.programs.map((p,i)=>`<button class="person-row" data-program="${p.id}"><div class="avatar ${i%2?'sage':'sand'}">${esc(initials(p.name))}</div><div class="person-name"><strong>${esc(p.name)}</strong><small>${esc(p.goal)} · ${p.days} dage om ugen</small></div><div class="row-focus"><small>FORLØB</small>12 uger · ${p.minutes} min.</div><div class="row-status">${pill(p.status)}</div><span class="row-arrow">${icon('arrow',18)}</span></button>`).join('');}
function overview(){const awaiting=state.programs.filter(p=>p.status==='draft').length;return `${heading('DIT PERSONLIGE OVERBLIK','Plads til den enkelte.','Her begynder forløb, der passer til mennesket.',`<button class="btn primary" data-nav="questionnaire">${icon('plus',18)} Opret nyt forløb</button>`)}<div class="dashboard-grid"><section class="hero"><div class="hero-copy"><div class="eyebrow light"><span class="gold-dot"></span> DIN FAGLIGHED. DERES UDVIKLING.</div><h2>Personlig træning.<br><em>Hele vejen.</em></h2><p>Fra det første spørgsmål til den sidste gentagelse.<br>Du sætter retningen. Mennesket sætter tempoet.</p><button class="btn cream" data-nav="programs">Gennemgå forløb ${icon('arrow',18)}</button><div class="hero-caption"><span class="mini-line"></span> ALTID DIN GODKENDELSE FØR DELING</div></div><div class="hero-art" aria-hidden="true"><svg viewBox="0 0 340 370"><defs><linearGradient id="gold" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#d2b176"/><stop offset="1" stop-color="#6d7668"/></linearGradient></defs><circle cx="186" cy="185" r="133"/><circle cx="186" cy="185" r="106"/><path class="line" d="M50 300C140 300 72 190 174 190S210 70 310 70"/><path class="faint" d="M55 328C145 328 100 240 185 240S242 140 325 140"/><circle class="point" cx="174" cy="190" r="7"/><path class="cross" d="M167 190h14m-7-7v14"/></svg><div class="art-label"><span>12</span> UGER.<br>ÉT MENNESKE.</div></div></section><aside class="focus-card"><div class="eyebrow">LAVET MED OMTANKE</div><div class="focus-icon">${icon('shield',26)}</div><h3>Dit blik gør<br>det personligt.</h3><p>Gennemgå valgene, ret til og giv først adgang, når hele programmet passer.</p><div class="focus-bottom"><strong>${awaiting.toString().padStart(2,'0')}</strong><span>forløb venter på<br>din gennemgang</span><button aria-label="Åbn forløb" class="round-arrow" data-nav="programs">${icon('arrow',18)}</button></div></aside></div><div class="stats"><div class="stat"><span class="stat-icon">${icon('people')}</span><div><small>DINE FORLØB</small><strong>${state.programs.length.toString().padStart(2,'0')} <span>personlige udgangspunkter</span></strong></div></div><div class="stat"><span class="stat-icon">${icon('exercise')}</span><div><small>ØVELSESBANK</small><strong>${exercises.length} <span>øvelser til gennemgang</span></strong></div></div><div class="stat"><span class="stat-icon">${icon('place')}</span><div><small>TRÆNINGSSTEDER</small><strong>${state.places.length.toString().padStart(2,'0')} <span>med hver deres udstyr</span></strong></div></div></div><div class="section-title"><div><div class="eyebrow">FRA SVAR TIL RETNING</div><h2>Forløb på dit bord</h2></div><button class="text-btn" data-nav="programs">Se alle forløb ${icon('arrow',17)}</button></div><section class="people-list">${programRows()}</section><section class="bottom-grid"><article class="editorial-card"><span class="number-label">01 / TILGANG</span><h3>Udvikling før automatik.</h3><p>Belastning og mængde følger personen. Ingen faste vægtstigninger. Ingen programmer på autopilot.</p><button class="text-btn" data-nav="knowledge">Se vidensgrundlaget ${icon('arrow',16)}</button></article><article class="editorial-card equipment-teaser"><span class="number-label">02 / RAMMER</span><h3>Samme mål. Andre muligheder.</h3><p>Intet slædeudstyr? Se hvilke dele af træningen alternativerne kan dække, og hvad der stadig mangler.</p><button class="text-btn" data-nav="places">Udforsk træningssteder ${icon('arrow',16)}</button></article></section>`;}
async function loadClients(){
 clientsError='';clientRows=null;if(view==='clients')render();
 try{if(demo){clientRows=state.programs.map(p=>({key:'email:'+p.answers.email,name:p.name,email:p.answers.email,programs:1,approved:p.status==='approved'?1:0,protected:false,account:false}));}else{const r=await fetch('/api/clients',{cache:'no-store'}),body=await r.json();if(!r.ok)throw Error(body.error);clientRows=body.clients;}}
 catch(e){clientsError=e.message||'Oversigten kunne ikke hentes.';}
 if(view==='clients')render();
}
function clientsView(){return `${heading('MENNESKENE BAG FORLØBENE','Dine klienter.','Forløb og loginprofiler samlet ét sted.',`<button class="btn secondary" data-action="refresh-clients">Opdater oversigt</button>`)}<section class="panel client-register"><div class="section-title compact"><h2>Klientoversigt</h2><span class="muted">${clientRows?clientRows.filter(c=>!c.protected).length+' personer':'Privat og adgangsbeskyttet'}</span></div>${clientsError?`<p role="alert">${esc(clientsError)}</p>`:!clientRows?'<p role="status">Henter klienter…</p>':clientRows.map((c,i)=>`<article class="client-record"><div class="avatar ${i%2?'sage':'sand'}">${esc(initials(c.name))}</div><div class="grow"><h3>${esc(c.name)}</h3><p>${esc(c.email||'Ingen mail registreret')}</p><div class="client-meta"><span>${c.programs} forløb · ${c.approved} godkendt</span><span>${c.protected?'Ejer · beskyttet':c.account?'Loginprofil oprettet':'Ingen loginprofil'}</span>${c.unfinished?'<span>Ufærdig besvarelse</span>':''}</div></div>${c.protected?'<span class="status green">Ejer kan ikke slettes</span>':`<button class="btn danger-outline" data-delete-client="${esc(c.key)}">Slet klient</button>`}</article>`).join('')||'<div class="empty"><p>Du har endnu ingen klienter. De vises her, når du registrerer deres mailadresse i spørgeskemaet.</p><button class="btn primary" data-nav="questionnaire">Opret et forløb</button></div>'}</section><section class="quiet-note">${icon('shield',20)}<p>Sletning fjerner personens forløb, gemte besvarelser og træningsregistreringer fra arbejdsrummet samt en eventuel loginprofil. Fælles træningssteder bevares. Invitationer og klientadgang tilbagekaldes også ved sletning. Klienten kan også inviteres til selv at svare under Skemabesvarelser.</p></section>`;}
function deleteClient(key){
 const c=clientRows?.find(c=>c.key===key);if(!c||c.protected)return;
 if(demo){state.programs=state.programs.filter(p=>'email:'+p.answers?.email!==key);current=state.programs[0]?.id;void loadClients();toast('Testpersonen er fjernet fra denne demo. Genindlæs for at nulstille.');return;}
 if(dirty||saving||savePaused){toast('Vent til ændringerne er gemt. Ved en konflikt skal siden genindlæses først.');return;}
 modal('Slet klient',`<p>Du er ved at slette <strong>${esc(c.name)}</strong>${c.email?' ('+esc(c.email)+')':''}.</p><div class="delete-summary"><strong>Dette fjernes</strong><ul><li>Alle personens ${c.programs} forløb og tilhørende besvarelser</li><li>Træningshistorik knyttet til forløbene</li>${c.unfinished?'<li>Den igangværende besvarelse</li>':''}<li>${c.account?'Loginprofil og tilhørende loginadgang':'Personen har endnu ingen loginprofil'}</li></ul></div><p>Handlingen kan ikke fortrydes i PTDahl. Eksporterede PDF filer og eventuelle sikkerhedskopier hos hostingudbyderen fjernes ikke af denne handling.</p><form id="delete-client-form"><div class="field"><label for="delete-confirm">Skriv SLET for at bekræfte</label><input id="delete-confirm" name="confirm" autocomplete="off" required pattern="SLET" placeholder="SLET"></div><p id="delete-error" role="alert"></p><div class="delete-actions"><button class="btn secondary" type="button" id="cancel-delete">Behold klient</button><button class="btn danger" type="submit">Slet klient permanent</button></div></form>`);
 const dialog=document.querySelector('#modal');document.querySelector('#cancel-delete').onclick=()=>dialog.close();
 const preventCancel=e=>{if(deleting)e.preventDefault();};dialog.oncancel=preventCancel;
 document.querySelector('#delete-client-form').onsubmit=async e=>{
  e.preventDefault();if(deleting)return;
  if(dirty||saving||savePaused){document.querySelector('#delete-error').textContent='Der er ændringer, som ikke er gemt. Luk vinduet og gem først.';return;}
  deleting=true;app.inert=true;dialog.querySelectorAll('button,input').forEach(el=>el.disabled=true);document.querySelector('#delete-error').textContent='Sletter… Hold siden åben.';
  try{
   const r=await fetch('/api/clients',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({key,revision,confirm:'SLET'})});const body=await r.json();
   if(body.data){state=body.data;revision=body.revision;dirty=false;current=state.programs[0]?.id;week=1;workout=null;setSaveMessage('Gemt privat i Neon');}
   if(!r.ok){if(r.status===409){savePaused=true;setSaveMessage('Genindlæs siden før flere ændringer',true);}throw Error(body.error||'Sletningen kunne ikke bekræftes.');}
   dialog.close();toast('Klienten og de tilknyttede oplysninger er slettet.');
  }catch(error){document.querySelector('#delete-error').textContent=error.message||'Forbindelsen blev afbrudt. Genindlæs oversigten for at kontrollere resultatet.';}
  finally{deleting=false;app.inert=false;dialog.querySelectorAll('button,input').forEach(el=>el.disabled=false);void loadClients();}
 };
}
function programsView(){const p=getP();if(!p)return overview();return `${heading('FRA SVAR TIL PERSONLIG PLAN','Forløb med retning.','Programbyggeren laver forslag. Du skal tilpasse og gennemgå hele forløbet før godkendelse.',`<button class="btn primary" data-nav="questionnaire">${icon('plus',18)} Nyt forløb</button>`)}<div class="program-tabs">${state.programs.map(x=>`<button class="${x.id===current?'active':''}" data-program="${x.id}">${esc(x.name)}</button>`).join('')}</div><div class="program-head panel"><div class="avatar large sand">${esc(initials(p.name))}</div><div class="grow"><div class="eyebrow">PERSONLIGT FORLØB · VERSION ${p.version}</div><h2>${esc(p.name)}</h2><p>${esc(p.goal)} · ${p.days} dage om ugen · op til ${p.minutes} minutter</p></div>${pill(p.status)}<button class="btn primary" data-action="invite" ${p.status!=='approved'?'disabled':''}>Inviter / del version</button><button class="btn secondary" data-action="client" ${p.status!=='approved'?'disabled':''}>${icon('play',15)} Brugervisning</button></div>${p.flags.length?`<section class="review-notice"><h3>${icon('shield')} Kræver din afklaring</h3>${p.flags.map((f,i)=>`<div class="flag-row"><div><strong>${esc(f.text)}</strong><small>Dokumentér afklaringen, før du godkender forløbet.</small></div><button class="btn small-btn secondary" data-resolve="${i}" ${f.resolved?'disabled':''}>${f.resolved?'Afklaret':'Markér afklaret'}</button></div>`).join('')}</section>`:''}<div class="program-layout"><div><div class="section-title compact"><h2>En uge ad gangen</h2><span class="muted">12 uger · 3 evalueringspunkter</span></div><div class="weeks" aria-label="Vælg uge">${p.weeks.map(w=>`<button class="${w.number===week?'selected':''} ${w.checkpoint?'checkpoint':''}" data-week="${w.number}"><small>UGE</small>${w.number}${w.checkpoint?'<i></i>':''}</button>`).join('')}</div><div class="week-info"><span>${esc(p.weeks[week-1].phase)}</span><span>${p.weeks[week-1].checkpoint?'Evaluering af udvikling og næste skridt':'Belastning ændres efter individuel vurdering'}</span></div>${p.sessions.map((s,si)=>sessionCard(s,si,p)).join('')}</div><aside class="review-column"><section class="panel review-panel"><div class="eyebrow">DIT FAGLIGE OVERBLIK</div><h3>Gør planen til deres.</h3><p>Ret øvelser, tid og mængde. Alle ændringer kræver ny godkendelse.</p><label for="command">Din rettelse</label><textarea id="command" rows="3" placeholder="Fx: Skift løb til cykel"></textarea><button class="btn secondary full" data-action="command">${icon('swap',16)} Vis forslag til rettelse</button><small class="help">Rettelsesfunktionen forstår: “Skift løb til cykel” og “Fjern hop”. Andre rettelser laves via Rediger på en øvelse. Ingen AI er tilkoblet.</small></section><section class="panel approval"><div class="eyebrow">KVALITET FØR DELING</div><h3>Du har sidste ord.</h3><label class="check-label"><input type="checkbox" id="acknowledge" ${p.acknowledged?'checked':''} ${p.status==='approved'?'disabled':''}><span>Jeg har gennemgået øvelser, alternativer, tid og afklaringer.</span></label><button class="btn primary full" data-action="approve" ${canApprove(p)?'':'disabled'}>${icon('check',17)} ${p.status==='approved'?'Godkendt':'Godkend forløb'}</button><p class="help">Efter godkendelse kan du dele denne version via et personligt invitationslink. Klienten ser først nye rettelser, når du godkender og deler igen. Der sendes endnu ingen automatisk mail.</p></section><section class="quiet-note">${icon('book',20)}<p>Startkilo er ikke gættet. Den konkrete belastning aftales ved indkøring og justeres efter udviklingen.</p></section></aside></div>`;}
function warmupList(s){return s.warmup_items?.length?`<ol class="warmup-list">${s.warmup_items.map(x=>{const e=exercises.find(e=>e.id===x.exercise_id);return `<li><strong>${esc(e?.name_da||x.exercise_id)}</strong><span>${x.duration_min} min. samlet</span><p>${esc(e?.instruction_da||'Gennemgå øvelsen med træneren.')}</p></li>`;}).join('')}</ol>`:'<p class="warmup-pending">Opvarmningen skal sammensættes manuelt efter din afklaring. Ældre forløb bevarer deres aftalte opvarmning.</p>';}
function editWarmup(si){const p=getP(),session=p.sessions[si],candidates=exercises.filter(e=>e.warmup_eligible&&available(e,p.inventory)),items=session.warmup_items||[];modal('Tilpas opvarmningen',`<form id="warmup-form"><p>Vælg op til seks bevægelser i den ønskede rækkefølge. Tid er samlet for begge sider og inkluderer rolige skift og pauser efter behov. Vælg bevægeudslag og indkøringssæt sammen med personen.</p>${Array.from({length:6},(_,i)=>`<div class="warmup-editor-row"><div class="field"><label>Trin ${i+1}<select name="exercise_${i}"><option value="">Udelad dette trin</option>${candidates.map(e=>`<option value="${e.id}" ${items[i]?.exercise_id===e.id?'selected':''}>${esc(e.name_da)}</option>`).join('')}</select></label></div><div class="field"><label>Minutter<input name="minutes_${i}" type="number" min="0.5" max="15" step="0.5" value="${items[i]?.duration_min||1}"></label></div></div>`).join('')}<p id="warmup-error" role="alert"></p><button class="btn primary full" type="submit">Gem opvarmning som ny kladde</button></form>`);document.querySelector('#warmup-form').onsubmit=event=>{event.preventDefault();const form=new FormData(event.target),next=[];for(let i=0;i<6;i++){const id=form.get('exercise_'+i);if(id)next.push({exercise_id:id,duration_min:Number(form.get('minutes_'+i))});}if(!next.length){document.querySelector('#warmup-error').textContent='Vælg mindst én bevægelse efter din faglige vurdering.';return;}const draft={...session,warmup_items:next,warmup_min:warmupMinutes(next)};draft.total_seconds=draft.warmup_min*60+draft.items.reduce((n,x)=>n+estimateSeconds(x),0);const errors=validateSession(draft,exercises,p.inventory).filter(error=>error!=='Der mangler øvelser.');if(errors.length){document.querySelector('#warmup-error').textContent=errors.join(' ');return;}Object.assign(session,draft);document.querySelector('#modal').close();changed(p);toast('Opvarmningen er gemt i en ny kladde. Gennemgå og godkend igen.');};}
function sessionCard(s,si,p){return `<section class="session-card"><div class="session-title"><span class="day-number">${String(si+1).padStart(2,'0')}</span><div class="grow"><h3>${esc(s.title)}</h3><small>${Math.ceil(s.total_seconds/60)} min. planlagt · ${s.warmup_min} min. opvarmning inkluderet</small></div>${icon('clock',18)}</div><div class="warmup">OPVARMNING <span>${s.warmup_min} min. · gennemgå bevægelser og varighed</span><button class="text-btn" data-warmup="${si}">Tilpas opvarmning</button></div>${warmupList(s)}${s.items.length?'':'<p class="warmup-pending">Ingen øvelser kunne matches til denne træningsdag. Tilføj øvelser efter din gennemgang.</p>'}${s.items.map((item,ii)=>{const e=exercises.find(e=>e.id===item.exercise_id);return `<div class="exercise-row"><span class="exercise-glyph">${icon(e.category==='kardio'||e.category==='loeb'?'clock':'exercise',22)}</span><div class="grow"><strong>${esc(e.name_da)}</strong><small>${item.duration_min?item.duration_min+' minutter':item.sets+' sæt × '+item.reps+' gentagelser'+(item.per_side?' pr. side':'')} · ${item.load_kg!=null?item.load_kg+' kg':'belastning aftales'}</small></div><button class="text-btn" data-edit="${si}:${ii}">Rediger</button></div>`;}).join('')}<button class="btn secondary" data-add-item="${si}">Tilføj øvelse</button>${s.substitutions.map(sub=>`<div class="substitution-note">${icon('swap',17)}<div><strong>Tilpasset det tilgængelige udstyr</strong><p>${esc(sub.limit)}</p></div></div>`).join('')}</section>`;}
const sections=[['profil','Lad os lære personen at kende.','Et godt forløb begynder med et godt udgangspunkt.'],['maal','Hvad skal træningen give?','Et hovedmål giver retning. Delmål giver plads til resten.'],['erfaring','Start der, hvor personen er.','Det nuværende niveau betyder mere end en etiket.'],['rammer','Få planen til at passe ind.','Tid, udstyr og hverdag skal hænge sammen.'],['loeb','Kondition på deres præmisser.','Løb er en mulighed. Ikke et krav for alle mål.'],['helbred','Giv plads til det, vi skal vide.','Relevante forhold skal afklares før godkendelse.'],['hverdag','Hverdagen er en del af planen.','Overskud og restitution tæller også.'],['praeferencer','Gør plads til lysten.','En plan skal også være en, personen har lyst til at følge.'],['samtykke','Information om besvarelsen.','Besvarelsen og kladden gemmes i dit private arbejdsrum.'],['afklaring','Noget vi skal tale om?','Du har altid den sidste vurdering.']];
const options={sex:['Kvinde','Mand','Andet','Ønsker ikke at oplyse'],primary_goal:['Bedre form','Styrke','Muskelmasse','Løb 5 km','HYROX','Mobilitet','Hverdagsfunktion','Andet'],secondary_goals:['Kondition','Styrke','Balance','Bevægelighed','Træningsvane','Andet'],event_type:['5 km','Anden løbedistance','HYROX Single','HYROX Doubles','HYROX Relay','Andet'],strength_history:['Ingen','Under en gang ugentligt','1 til 2 gange','3 eller flere gange'],preferred_days:['Mandag','Tirsdag','Onsdag','Torsdag','Fredag','Lørdag','Søndag','Skiftende'],location:['Hjemme','Fitnesscenter','Udendørs','HYROX center','Andet'],run_ability:['Ja','Kan men ønsker ikke','Ønsker men kan ikke nu','Nej','Usikker'],alternatives:['Gang','Cykel','Roning','SkiErg','Crosstrainer','Svømning','Andet'],floor_transfer:['Ja','Med støtte','Nej','Usikker'],pregnancy_postpartum:['Ja','Nej','Ønsker at tale med dig om det','Ønsker ikke at oplyse'],sleep:['God','Varierende','Dårlig','Ønsker ikke at oplyse'],recovery:['God','Varierende','Begrænset'],barriers:['Tid','Smerter','Træthed','Usikker teknik','Motivation','Støj og mange mennesker','Andet'],presentation:['Korte tekster','Illustrationer','Video','En øvelse ad gangen','Fast ugeplan']};
function visibleQuestion(q){const a=state.answers;if(q.section==='helbred'&&['pain_location','pain_context','pain_severity'].includes(q.key))return a.current_symptoms&&a.current_symptoms!=='Nej';if(['current_run','weekly_run'].includes(q.key))return a.run_ability==='Ja';if(['event_type','event_date'].includes(q.key))return ['HYROX','Løb 5 km'].includes(a.primary_goal);if(q.key==='race_class')return a.primary_goal==='HYROX';return true;}
function field(q){const val=state.answers[q.key]??'',opts=options[q.key]||(q.type.startsWith('yes_no')?['Ja','Nej',...(q.type.includes('unsure')?['Usikker']:[])]:null);const label=q.label_da.split('?')[0]+'?';if(q.key==='equipment')return `<div class="field wide"><label for="place-choice">Hvilket træningssted skal forløbet passe til?</label><select id="place-choice" name="__place">${state.places.map(p=>`<option value="${p.id}" ${p.id===selectedPlace?'selected':''}>${esc(p.name)}</option>`).join('')}</select><small>Udstyr og begrænsninger administreres under Træningssteder.</small></div>`;if(['health_consent','privacy_ack'].includes(q.key))return `<div class="field wide"><label class="check-label"><input type="checkbox" name="${q.key}" ${val?'checked':''}><span>${q.key==='health_consent'?'Jeg har afklaret udtrykkeligt samtykke til den nødvendige behandling af relevante helbredsoplysninger.':'Jeg har informeret personen om formål, adgang, opbevaring og mulighed for at få sine oplysninger slettet.'}</span></label></div>`;if(opts){if(q.type.startsWith('multi'))return `<fieldset class="field wide"><legend>${esc(label)}</legend><div class="choice-grid">${opts.map(o=>`<label class="choice"><input type="checkbox" name="${q.key}" value="${esc(o)}" ${Array.isArray(val)&&val.includes(o)?'checked':''}><span>${esc(o)}</span></label>`).join('')}</div></fieldset>`;return `<div class="field"><label for="q-${q.key}">${esc(label)}${q.required?' <span class="required">*</span>':''}</label><select id="q-${q.key}" name="${q.key}" ${q.required?'required':''}><option value="">Vælg et svar</option>${opts.map(o=>`<option ${val===o?'selected':''}>${esc(o)}</option>`).join('')}</select></div>`;}
const isNum=/number|integer|scale/.test(q.type),isDate=q.type.startsWith('date');if(q.type.startsWith('text')||q.type.startsWith('bodymap'))return `<div class="field ${q.key==='name'?'':'wide'}"><label for="q-${q.key}">${esc(label)}${q.required?' <span class="required">*</span>':''}</label>${q.key==='name'?`<input id="q-${q.key}" name="${q.key}" maxlength="100" autocomplete="off" value="${esc(val)}" placeholder="Personens navn" required>`:`<textarea id="q-${q.key}" name="${q.key}" rows="3" maxlength="1500" ${q.required?'required':''}>${esc(val)}</textarea>`}</div>`;return `<div class="field"><label for="q-${q.key}">${esc(label)}${q.required?' <span class="required">*</span>':''}</label><input id="q-${q.key}" name="${q.key}" type="${isNum?'number':isDate?'date':'email'}" ${isNum?'step="1" min="0"':''} ${q.key==='age'?'min="18" max="110"':q.key==='days_per_week'?'min="1" max="6"':q.key==='minutes'?'min="15" max="120"':''} value="${esc(val)}" ${q.required?'required':''} ${q.key==='email'?'placeholder="navn@example.com" autocomplete="off"':''}></div>`;}
function questionnaireView(){const [section,title,desc]=sections[step];return `${heading('DET PERSONLIGE UDGANGSPUNKT','Spørg. Lyt. Forstå.','Udfyld sammen med personen, eller inviter personen til selv at svare.',`<button class="btn primary" data-action="new-intake">Inviter til spørgeskema</button>`)}<div class="questionnaire-layout"><aside class="steps">${sections.map(([id,title],i)=>`<button data-step="${i}" class="${step===i?'active':''}"><span>${i<step?icon('check',14):String(i+1).padStart(2,'0')}</span>${({profil:'Profil',maal:'Mål og motivation',erfaring:'Træningserfaring',rammer:'Tid og udstyr',loeb:'Løb og kondition',helbred:'Helbred og hensyn',hverdag:'Hverdag',praeferencer:'Præferencer',samtykke:'Information',afklaring:'Afslutning'})[id]}</button>`).join('')}<p>52 felter med relevant opfølgning. Oplys kun det nødvendige. Svarene gemmes i dit private arbejdsrum.</p></aside><section class="panel questionnaire"><div class="form-top"><span class="eyebrow">TRIN ${step+1} AF ${sections.length}</span><span>${Math.round((step+1)/sections.length*100)} %</span></div><div class="progress-track"><div style="width:${(step+1)/sections.length*100}%"></div></div><h2>${title}</h2><p>${desc}</p><form id="question-form"><div class="fields">${questions.filter(q=>q.section===section&&visibleQuestion(q)).map(field).join('')}</div><div class="form-bottom"><button type="button" class="text-btn" data-action="previous" ${step===0?'disabled':''}>Tilbage</button><span class="muted">* Udfyldes</span><button class="btn primary" type="submit">${step===sections.length-1?'Lav programudkast':'Gem og fortsæt'} ${icon('arrow',17)}</button></div></form></section></div>`;}
function exerciseView(){const filtered=exercises.filter(e=>(!warmupOnly||e.warmup_eligible)&&(!exerciseBrand||brandsFor(e).includes(exerciseBrand))&&(!exerciseGear||e.required_equipment.some(k=>equipmentKeys[k]?.includes(exerciseGear)))&&(!exerciseFilter||e.category===exerciseFilter)&&(!exerciseSearch||`${e.name_da} ${e.category} ${e.movement_pattern} ${e.machine_brand||''} ${e.machine_model||''} ${machineSearchText(e)} ${e.required_equipment.map(k=>k).join(' ')}`.toLowerCase().includes(exerciseSearch.toLowerCase())));return `${heading('ET FUNDAMENT AT BYGGE VIDERE PÅ','Øvelser med et formål.','Opret øvelser med dine egne instruktioner, udstyrskrav og kilder.',`<button class="btn primary" data-action="new-exercise">${icon('plus',17)} Opret øvelse</button>`)}<div class="toolbar"><div class="search-input">${icon('search',18)}<input id="exercise-search" aria-label="Søg i øvelser" value="${esc(exerciseSearch)}" placeholder="Søg efter øvelse eller bevægelse…"></div><select id="exercise-category" aria-label="Filtrer kategori"><option value="">Alle kategorier</option>${['styrke','hyrox','kardio','loeb','mobilitet','balance'].map(c=>`<option value="${c}" ${c===exerciseFilter?'selected':''}>${{loeb:'Løb',hyrox:'HYROX'}[c]||c[0].toUpperCase()+c.slice(1)}</option>`).join('')}</select><select id="exercise-equipment" aria-label="Filtrer udstyr"><option value="">Alt udstyr</option>${Object.entries(gear).filter(([k])=>k!=='none').map(([k,v])=>`<option value="${k}" ${exerciseGear===k?'selected':''}>${esc(v)}</option>`).join('')}</select><select id="exercise-brand" aria-label="Filtrer mærke"><option value="">Alle mærker</option>${[...new Set(exercises.flatMap(brandsFor))].sort().map(b=>`<option ${exerciseBrand===b?'selected':''}>${esc(b)}</option>`).join('')}</select><label class="check-label"><input id="warmup-only" type="checkbox" ${warmupOnly?'checked':''}> Opvarmning</label><span class="muted">${filtered.length} øvelser</span></div><div class="exercise-grid">${filtered.map(e=>`<button class="exercise-tile" data-exercise="${e.id}"><div class="exercise-art"><span>${icon(e.category==='balance'?'shield':e.category==='mobilitet'?'sun':e.category==='kardio'||e.category==='loeb'?'clock':'exercise',42)}</span><span class="exercise-id">${e.id}</span></div><div class="tile-copy"><span class="eyebrow">${e.category==='loeb'?'LØB':esc(e.category.toUpperCase())}</span><h3>${esc(e.name_da)}</h3><p>${esc(e.instruction_da)}</p>${brandsFor(e).length?`<small class="machine-brands">${esc(brandsFor(e).join(' · '))}</small>`:''}<div class="tile-bottom"><span>${e.review_status==='coach_reviewed'?'Gennemgået af træner':'Afventer gennemgang'}</span>${icon('arrow',17)}</div></div></button>`).join('')||'<div class="panel empty">Ingen øvelser matcher din søgning.</div>'}</div>`;}
function placesView(){const place=state.places.find(x=>x.id===selectedPlace)||state.places[0];return `${heading('RAMMERNE SKAL PASSE TIL PERSONEN','Træn dér, hvor livet er.','Hvert sted har sit eget udstyr. Alternativer vurderes efter formål.',`<button class="btn primary" data-action="new-place">${icon('plus',17)} Nyt træningssted</button>`)}<div class="place-layout"><aside class="places-menu">${state.places.map(p=>`<button class="place-tab ${p.id===place.id?'active':''}" data-place="${p.id}">${icon('place',22)}<span><strong>${esc(p.name)}</strong><small>${esc(p.type)} · ${p.inventory.length} udstyrstyper</small></span>${icon('chevron',16)}</button>`).join('')}<div class="quiet-note"><p>Ændring af et sted ændrer aldrig et allerede godkendt forløb. Du skal lave en ny version.</p></div></aside><div><section class="panel equipment-panel"><div class="eyebrow">DET KONKRETE TRÆNINGSSTED</div><h2>${esc(place.name)}</h2><p>${esc(place.note)}</p>${place.brands?`<p class="help">Mærker: ${esc(place.brands)} · <a href="${esc(place.url)}" target="_blank" rel="noopener noreferrer">Centrets oplysninger</a></p>`:''}<fieldset><legend>Hvad er tilgængeligt?</legend><div class="equipment-grid">${Object.entries(gear).filter(([k])=>k!=='none').map(([k,name])=>`<label class="equipment-option"><input type="checkbox" data-gear="${k}" ${place.inventory.includes(k)?'checked':''}><span>${icon(k==='route'?'place':'exercise',18)} ${name}</span></label>`).join('')}</div></fieldset><div class="equipment-count">${icon('check',17)} ${exercises.filter(e=>available(e,place.inventory)).length} af ${exercises.length} øvelser matcher stedets udstyr. Egnethed skal stadig vurderes.</div></section><div class="section-title"><div><div class="eyebrow">HYROX MED DE MULIGHEDER, DER ER</div><h2>Når udstyret mangler</h2></div></div>${['E041','E042','E033','E046'].map(id=>{const e=exercises.find(x=>x.id===id),alt=alternatives(id,exercises,place.inventory);return `<section class="alternative-card"><div class="alt-title"><span class="exercise-glyph">${icon('swap',21)}</span><div><h3>${esc(e.name_da)}</h3><small>${available(e,place.inventory)?'Udstyret er tilgængeligt':'Udstyret er ikke tilgængeligt'}</small></div></div><div class="alt-options">${alt.options.map(e=>`<button data-exercise="${e.id}">${esc(e.name_da)} ${icon('arrow',14)}</button>`).join('')||'<span>Intet registreret alternativ med dette udstyr. Vælg manuelt.</span>'}</div><p><strong>Træningsformål:</strong> ${esc(alt.purpose)}</p><p class="help">${esc(alt.limit)}</p><span class="review-label">DELVIST ALTERNATIV · KRÆVER DIN VURDERING</span></section>`;}).join('')}</div></div>`;}
function knowledgeView(){return `${heading('VIDEN FØR AUTOMATIK','Et grundlag med omtanke.','Kilder, afgrænsninger og tydelige skel mellem viden og forslag.')}<section class="principles"><article><span>01</span><h3>Personen før skabelonen.</h3><p>Erfaring, tid, mål, udstyr og hensyn bestemmer udgangspunktet.</p></article><article><span>02</span><h3>Udvikling før vægtstigning.</h3><p>Ingen automatisk progression. Justering kræver din vurdering.</p></article><article><span>03</span><h3>Faglighed før deling.</h3><p>Alle forslag og alternativer skal gennemgås, før personen får adgang.</p></article></section><div class="section-title"><h2>Vidensbankens første kilder</h2><span class="muted">Kontrolleret 3. november 2026</span></div><div class="sources">${sources.map(s=>`<article class="source-card"><span>${s.id}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.summary)}</p><small>${s.id==='S10'?'Kun oversigten er identificeret. Konkurrencedetaljer mangler verificering.':'Kildeopsummering. Ingen automatisk individuel ordination.'}</small></div>${s.url?`<a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer" class="icon-btn" aria-label="Åbn kilde ${s.id}">${icon('arrow',18)}</a>`:'<span class="review-label">BRUGERREFERENCE</span>'}</article>`).join('')}</div>`;}
function settingsView(){if(demo)return `${heading('DEMONSTRATION','Vis mulighederne frem.','Alle personer, programmer og udstyrslister i demoen er fiktive.')}<section class="panel settings-panel"><h2>Prøv det hele med ro i maven.</h2><p>Du kan gennemgå forløb, udfylde et spørgeskema, tilpasse øvelser, starte en træning og oprette øvelsesforslag. Alle ændringer bliver kun i denne åbne side og forsvinder ved genindlæsning. Der sendes ingen mails, og den rigtige database ændres ikke.</p><a class="btn primary" href="/demo">Nulstil demoen</a><a class="btn secondary" href="/">Til login</a></section>`;return `${heading('DIT PRIVATE ARBEJDSRUM','Et stærkt fundament.','Login, lagring og det næste arbejde med PTDahl.')}<section class="panel settings-panel"><div class="eyebrow">PTDAHL · VERSION 0.9</div><h2>Kun din konto har adminadgang.</h2><p>Du er logget ind med en bekræftet mailadresse. Besvarelser, forløb, steder og træningsregistreringer gemmes privat i Neon. Tidligere fiktive demodata er ikke importeret.</p><div class="setup-row"><span class="status green"><i></i>Aktivt</span><div><strong>Login, privat lagring og klientadministration</strong><p>Adminadgang kontrolleres på serveren. En anden konto kan ikke læse eller ændre dit arbejdsrum. Under Klienter kan du slette personer og tilhørende oplysninger. Ejerkontoen er beskyttet mod sletning.</p></div></div><div class="setup-row"><span class="status green"><i></i>Forbundet</span><div><strong>GitHub, Vercel og Neon</strong><p>Ændringer i GitHub udgives automatisk. Vidensbank og private oplysninger holdes adskilt.</p></div></div><div class="setup-row"><span class="status amber"><i></i>Næste etape</span><div><strong>Invitation og klientadgang</strong><p>Personlige invitationslinks giver klienten adgang til ét godkendt forløb, PDF og træningsregistrering. Du kan tilbagekalde adgang under Invitationer. Automatisk invitationsmail kræver en mailtjeneste. Klienten kan også inviteres til selv at svare under Skemabesvarelser.</p></div></div><div class="setup-row"><span class="status amber"><i></i>Gennemgang</span><div><strong>Programgenerator og øvelser</strong><p>Programbyggeren bruger enkle skabeloner til forslag. Øvelser, hensyn og progression kræver din gennemgang. Ikoner er dekorative; tekniske illustrationer mangler endnu.</p></div></div><p class="private-note">Før rigtige klientoplysninger registreres, skal din information om behandling, samtykke, sletning og databehandlerforhold være på plads.</p><button class="btn secondary" data-action="signout">Log ud</button></section>`;}
function clientView(){const p=getP();if(p.status!=='approved')return '<section class="panel"><h2>Forløbet er endnu ikke godkendt.</h2></section>';if(workout)return workoutView();return `${heading('FORHÅNDSVISNING · BRUGERENS OPLEVELSE','Din træning. Dit tempo.',`Hej ${esc(p.name.split(' ')[0])}. Her er din godkendte plan.`,`<button class="btn secondary" data-action="back-admin">Tilbage til gennemgang</button>`)}<section class="client-hero"><div><div class="eyebrow light">${esc(p.goal.toUpperCase())} · 12 UGER</div><h2>Ét godt skridt<br><em>ad gangen.</em></h2><p>${p.days} træningsdage · op til ${p.minutes} minutter · version ${p.version}</p></div><div class="week-badge"><strong>${week.toString().padStart(2,'0')}</strong><span>UGE AF 12</span></div></section><div class="client-toolbar"><label for="client-week">Din uge <select id="client-week">${p.weeks.map(w=>`<option value="${w.number}" ${w.number===week?'selected':''}>Uge ${w.number} · ${w.phase}</option>`).join('')}</select></label><button class="btn secondary" data-action="print">${icon('download',17)} Udskriv / gem PDF</button></div><p class="muted">Mængde og vægt ændres sammen med din træner. Evaluering i uge 4, 8 og 12.</p><div class="client-days">${p.sessions.map((s,i)=>{const progress=state.workouts[p.id+':'+week+':'+s.id];return `<article class="panel client-day"><div class="eyebrow">TRÆNING ${i+1}</div><h3>${esc(s.title)}</h3><p>${Math.ceil(s.total_seconds/60)} min. · ${s.items.length} øvelser</p><p class="help">Opvarmning: ${s.warmup_items?.map(x=>esc(exercises.find(e=>e.id===x.exercise_id)?.name_da||x.exercise_id)).join(' · ')||'Efter aftale med træneren'}</p><div class="day-exercises">${s.items.map(x=>esc(exercises.find(e=>e.id===x.exercise_id).name_da)).join('<span> / </span>')}</div><button class="btn primary full" data-start="${s.id}">${icon('play',15)} ${progress?.done?'Se gennemført træning':progress?'Fortsæt træning':'Start træning'}</button>${progress?.done?'<small class="completion">'+icon('check',14)+' Gennemført</small>':''}</article>`;}).join('')}</div><div class="print-only"><h1>PTDahl · ${esc(p.name)}</h1><p>Godkendt program · Version ${p.version} · ${new Date().toLocaleDateString('da-DK')}</p>${p.weeks.map(w=>`<section class="print-week"><h2>Uge ${w.number} · ${w.phase}</h2><p>${esc(w.progression)}${w.checkpoint?' Evaluering med træneren.':''}</p>${p.sessions.map(s=>`<h3>${esc(s.title)} · ${Math.ceil(s.total_seconds/60)} min.</h3><p>Opvarmning: ${s.warmup_min} minutter, tilpasses af træneren.</p>${warmupList(s)}<table><thead><tr><th>Øvelse</th><th>Mængde</th><th>Pause</th><th>Belastning</th></tr></thead><tbody>${s.items.map(x=>{const e=exercises.find(e=>e.id===x.exercise_id);return `<tr><td><strong>${esc(e.name_da)}</strong><br>${esc(e.instruction_da)}</td><td>${x.duration_min?x.duration_min+' min.':x.sets+' × '+x.reps+(x.per_side?' pr. side':'')}</td><td>${x.rest_sec?x.rest_sec+' sek.':'Efter behov'}</td><td>${x.load_kg!=null?x.load_kg+' kg':'Aftales med træneren'}<br>${esc(x.effort)}</td></tr>`;}).join('')}</tbody></table>${s.substitutions.map(sub=>`<p>Alternativ: ${esc(sub.limit)}</p>`).join('')}`).join('')}</section>`).join('')}</div>`;}
function workoutView(){const p=getP(),s=p.sessions.find(s=>s.id===workout),key=p.id+':'+week+':'+s.id;const progress=state.workouts[key]??{index:-1,logs:[],done:false};state.workouts[key]=progress;if(!progress.done&&progress.index<0&&s.warmup_items?.length){const n=Math.min(progress.warmup_index||0,s.warmup_items.length-1),x=s.warmup_items[n],e=exercises.find(e=>e.id===x.exercise_id);return `${heading('OPVARMNING · EN BEVÆGELSE AD GANGEN',esc(s.title),`Uge ${week} · Opvarmning ${n+1} af ${s.warmup_items.length}`,`<button class="btn secondary" data-action="finish-workout">Gem og hold pause</button>`)}<section class="panel workout-stage"><div class="workout-symbol">${icon('sun',58)}</div><div class="eyebrow">DYNAMISK OPVARMNING</div><h2>${esc(e?.name_da||x.exercise_id)}</h2><p>${esc(e?.instruction_da||'Følg aftalen med din træner.')}</p><div class="workout-dose"><strong>${x.duration_min}</strong> minutter samlet</div><p class="help">Rolige bevægelser i aftalt bevægeudslag. Tid er samlet for begge sider og skift. Stop ved nye smerter eller symptomer.</p><button class="btn primary full" data-action="next-exercise">${n+1<s.warmup_items.length?'Færdig · næste opvarmningsøvelse':'Opvarmning færdig · begynd træningen'}</button></section>`;}if(progress.done)return `${heading('TRÆNING GENNEMFØRT','Godt arbejde.','Du er kommet igennem dagens plan.')}<section class="panel workout-finish"><div class="success-circle">${icon('check',38)}</div><h2>Et skridt tættere på.</h2><p>${esc(s.title)} · uge ${week}</p><p>Registreringerne gemmes privat. Dette er trænerens forhåndsvisning af træningsflowet.</p><button class="btn primary" data-action="finish-workout">Tilbage til mit program ${icon('arrow',17)}</button></section>`;const item=progress.index<0?null:s.items[progress.index],e=item?exercises.find(e=>e.id===item.exercise_id):null;return `${heading('EN ØVELSE AD GANGEN',esc(s.title),`Uge ${week} · ${progress.index<0?'Opvarmning':'Øvelse '+(progress.index+1)+' af '+s.items.length}`,`<button class="btn secondary" data-action="finish-workout">Gem og hold pause</button>`)}<section class="panel workout-stage"><div class="workout-progress">${Array.from({length:s.items.length+1},(_,i)=>`<span class="${i<=progress.index+1?'filled':''}"></span>`).join('')}</div><div class="workout-symbol">${icon(e?'exercise':'sun',58)}</div><div class="eyebrow">${e?esc(e.category.toUpperCase()):'EN ROLIG START'}</div><h2>${e?esc(e.name_da):'Opvarmning'}</h2><p>${e?esc(e.instruction_da):'Rolig indkøring efter aftale med din træner. Tilpas bevægelserne til din dagsform.'}</p><div class="workout-dose">${item?item.duration_min?'<strong>'+item.duration_min+'</strong> minutter':'<strong>'+item.sets+' × '+item.reps+'</strong> gentagelser'+(item.per_side?' pr. side':''):'<strong>'+s.warmup_min+'</strong> minutter'}</div>${item?`<div class="workout-details"><span>Pause: ${item.rest_sec||'efter behov'} ${item.rest_sec?'sek.':''}</span><span>${item.load_kg!=null?item.load_kg+' kg':'Belastning aftales med træneren'}</span></div><p class="help">${esc(item.effort)}</p><div class="workout-log"><label>Faktisk vægt (valgfri)<input type="number" min="0" max="1000" step="0.5" id="actual-load" placeholder="kg"></label><label>Oplevet anstrengelse<select id="actual-effort"><option value="">Vælg eventuelt</option><option>Let</option><option>Moderat</option><option>Hård</option><option>For hård</option></select></label></div>`:''}<button class="btn primary full workout-next" data-action="next-exercise">${icon('check',20)} ${item?'Færdig med alle sæt · næste øvelse':'Opvarmning færdig · begynd'}</button>${item?'<button class="text-btn" data-action="skip-exercise">Spring øvelsen over</button>':''}<p class="help">Dekorativt ikon. Teknikillustrationer tilføjes senere. Ved nye eller bekymrende symptomer skal du stoppe og få relevant rådgivning.</p></section>`;}
function modal(title,body,foot=''){const d=document.querySelector('#modal');d.innerHTML=`<div class="modal-head"><h2 id="modal-title">${title}</h2><button class="icon-btn" data-close aria-label="Luk">${icon('close')}</button></div>${body}${foot?`<div class="modal-foot">${foot}</div>`:''}`;d.querySelector('[data-close]').onclick=()=>d.close();d.showModal();}
function showExercise(id){const e=exercises.find(x=>x.id===id);modal(esc(e.name_da),`<div class="eyebrow">${esc(e.category.toUpperCase())} · ${e.id}</div><p>${esc(e.instruction_da)}</p><div class="detail-box"><strong>Udstyr${e.machine_brand?' · '+esc(e.machine_brand)+' '+esc(e.machine_model||''):''}</strong><p>${esc(e.required_equipment.map(k=>equipmentChoices[k]||k).join(', '))}</p></div><div class="detail-box"><strong>Kilde og gennemgang</strong><p>${e.source_ids.length?'Matchende offentligt eksempel: '+e.source_ids.map(id=>esc(sources.find(x=>x.id===id).title)).join(', '):'Redaktionelt øvelsesforslag. Ikke individuelt kildeverificeret.'}</p><p>${e.review_status==='coach_reviewed'?'Gennemgået af træner. Individuel egnethed vurderes separat.':'Afventer faglig gennemgang.'}</p>${e.source_url?`<p><a href="${esc(e.source_url)}" target="_blank" rel="noopener noreferrer">Åbn kilde</a></p>`:''}</div>${e.machine_references?.length?`<section class="machine-references"><h3>Maskineksempler fra kataloger</h3><p>Samme grundbevægelse kan findes hos flere mærker. Kontroller altid den konkrete indstilling og bevægebane. Kilo overføres ikke direkte mellem modeller.</p>${e.machine_references.map(r=>`<a ${r.url?`href="${esc(r.url)}" target="_blank" rel="noopener noreferrer"`:''}><strong>${esc(r.brand)}</strong> ${esc(r.series)} · ${esc(r.model)}<small>${r.match_status==='coach_recorded_verify_local_setup'?'Registreret af træner':'Katalogmatch'} · lokal indstilling skal kontrolleres</small></a>`).join('')}</section>`:''}<p class="help">En registrering i øvelsesbanken er ikke en vurdering af individuel egnethed ved skader.</p>`,`<button class="btn secondary" id="add-machine-reference">Tilføj mærke og model</button><button class="btn primary" id="exercise-variant">Brug som skabelon til ny variant</button>`);document.querySelector('#exercise-variant').onclick=()=>editExercise(e);document.querySelector('#add-machine-reference').onclick=()=>addMachineReference(e);}
function changed(p){p.version++;p.status='draft';p.acknowledged=false;p.approved_at=null;save();render();}
function editItem(si,ii){const p=getP(),s=p.sessions[si],adding=ii===undefined,x=adding?{sets:1,reps:8,rest_sec:60,load_kg:null}:s.items[ii];modal(adding?'Tilføj øvelse':'Tilpas øvelsen',`<form id="edit-form"><div class="field"><label>Øvelse med stedets udstyr<select name="exercise_id" required><option value="">Vælg øvelse</option>${exercises.filter(e=>available(e,p.inventory)).map(e=>`<option value="${e.id}" ${x.exercise_id===e.id?'selected':''}>${esc(e.name_da)}</option>`).join('')}</select></label></div><div class="fields"><div class="field"><label>Sæt<input type="number" name="sets" min="1" max="10" value="${x.sets||1}" required></label></div><div class="field"><label>Gentagelser<input type="number" name="reps" min="1" max="100" value="${x.reps||8}" required></label></div><div class="field"><label>Varighed i minutter (tom ved gentagelser)<input type="number" name="duration_min" min="1" max="120" value="${x.duration_min||''}"></label></div><div class="field"><label>Pause i sekunder<input type="number" name="rest_sec" min="0" max="600" value="${x.rest_sec}" required></label></div><div class="field"><label>Belastning i kg (valgfri)<input type="number" name="load_kg" min="0" max="1000" step="0.5" value="${x.load_kg??''}"></label></div><div class="field"><label class="check-label"><input type="checkbox" name="per_side" ${x.per_side?'checked':''}> Gentagelser pr. side</label></div></div><p class="help">Ændringen opretter en ny kladde, som skal godkendes igen. En manuel udskiftning af en øvelse kræver din vurdering af træningsformålet.</p><button class="btn primary full" type="submit">Gem ny kladde</button></form>`);document.querySelector('#edit-form').onsubmit=ev=>{ev.preventDefault();const f=new FormData(ev.target),next={...x,exercise_id:f.get('exercise_id'),sets:+f.get('sets'),reps:+f.get('reps'),duration_min:f.get('duration_min')?+f.get('duration_min'):null,rest_sec:+f.get('rest_sec'),load_kg:f.get('load_kg')!==''?+f.get('load_kg'):null,per_side:f.get('per_side')==='on'};const draft=structuredClone(s);if(adding)draft.items.push(next);else draft.items[ii]=next;draft.total_seconds=draft.warmup_min*60+draft.items.reduce((n,x)=>n+estimateSeconds(x),0);const err=validateSession(draft,exercises,p.inventory);if(err.length){toast(err.join(' '));return;}s.items=draft.items;s.total_seconds=draft.total_seconds;s.substitutions=s.substitutions.filter(sub=>sub.to!==x.exercise_id);document.querySelector('#modal').close();changed(p);toast('Ny kladde gemt. Gennemgå og godkend igen.');};}
function collectForm(){const form=document.querySelector('#question-form');if(!form)return;const data=new FormData(form);for(const q of questions.filter(q=>q.section===sections[step][0]&&visibleQuestion(q))){if(q.key==='equipment'){selectedPlace=data.get('__place')||selectedPlace;continue;}if(q.type.startsWith('multi'))state.answers[q.key]=data.getAll(q.key);else if(['health_consent','privacy_ack'].includes(q.key))state.answers[q.key]=data.has(q.key);else state.answers[q.key]=data.get(q.key)||'';}save();}
function bind(){document.querySelectorAll('[data-add-item]').forEach(el=>el.onclick=()=>editItem(Number(el.dataset.addItem)));document.querySelectorAll('[data-intake-answers]').forEach(el=>el.onclick=()=>showIntakeAnswers(el.dataset.intakeAnswers));document.querySelectorAll('[data-intake-program]').forEach(el=>el.onclick=()=>openIntakeProgram(el.dataset.intakeProgram));document.querySelectorAll('[data-intake-revoke]').forEach(el=>el.onclick=()=>revokeIntake(el.dataset.intakeRevoke));document.querySelectorAll('[data-revoke]').forEach(el=>el.onclick=()=>revokeInvitation(el.dataset.revoke));document.querySelectorAll('[data-warmup]').forEach(el=>el.onclick=()=>editWarmup(+el.dataset.warmup));document.querySelectorAll('[data-delete-client]').forEach(el=>el.onclick=()=>deleteClient(el.dataset.deleteClient));document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>go(el.dataset.nav));document.querySelector('.brand').onclick=ev=>{ev.preventDefault();go('overview');};document.querySelectorAll('[data-program]').forEach(el=>el.onclick=()=>{current=el.dataset.program;week=1;go('programs');});document.querySelectorAll('[data-week]').forEach(el=>el.onclick=()=>{week=+el.dataset.week;render();});document.querySelectorAll('[data-exercise]').forEach(el=>el.onclick=()=>showExercise(el.dataset.exercise));document.querySelectorAll('[data-edit]').forEach(el=>el.onclick=()=>editItem(...el.dataset.edit.split(':').map(Number)));document.querySelectorAll('[data-step]').forEach(el=>el.onclick=()=>{collectForm();step=+el.dataset.step;render();});document.querySelectorAll('[data-place]').forEach(el=>el.onclick=()=>{selectedPlace=el.dataset.place;render();});document.querySelectorAll('[data-gear]').forEach(el=>el.onchange=()=>{const p=state.places.find(x=>x.id===selectedPlace);p.inventory=el.checked?[...p.inventory,el.dataset.gear]:p.inventory.filter(x=>x!==el.dataset.gear);save();render();});document.querySelectorAll('[data-resolve]').forEach(el=>el.onclick=()=>{const p=getP();p.flags[+el.dataset.resolve].resolved=true;p.flags[+el.dataset.resolve].resolution_note='Afklaret af administrator';changed(p);});
const ack=document.querySelector('#acknowledge');if(ack)ack.onchange=()=>{getP().acknowledged=ack.checked;save();document.querySelector('[data-action="approve"]').disabled=!canApprove(getP());};
const wo=document.querySelector('#warmup-only');if(wo)wo.onchange=()=>{warmupOnly=wo.checked;render();};const search=document.querySelector('#exercise-search');if(search)search.oninput=()=>{const pos=search.selectionStart;exerciseSearch=search.value;render();const s=document.querySelector('#exercise-search');s.focus();s.setSelectionRange(pos,pos);};const brand=document.querySelector('#exercise-brand');if(brand)brand.onchange=()=>{exerciseBrand=brand.value;render();};const eq=document.querySelector('#exercise-equipment');if(eq)eq.onchange=()=>{exerciseGear=eq.value;render();};const cat=document.querySelector('#exercise-category');if(cat)cat.onchange=()=>{exerciseFilter=cat.value;render();};
const form=document.querySelector('#question-form');if(form){form.onchange=ev=>{collectForm();if(['run_ability','primary_goal','current_symptoms'].includes(ev.target.name))render();};form.onsubmit=ev=>{ev.preventDefault();collectForm();if(step<sections.length-1){step++;render();return;}try{for(const q of questions.filter(q=>q.required&&visibleQuestion(q))){const val=state.answers[q.key];if(q.key==='equipment')continue;if(val===''||val==null||Array.isArray(val)&&!val.length||['privacy_ack','health_consent'].includes(q.key)&&val!==true){step=sections.findIndex(s=>s[0]===q.section);render();toast('Udfyld de nødvendige svar før programmet laves.');return;}}const place=state.places.find(x=>x.id===selectedPlace);const p=makeDraft(state.answers,exercises,place.inventory);p.answers=structuredClone(state.answers);state.programs.push(p);state.answers={};current=p.id;week=1;save();go('programs');toast('Programudkast oprettet. Afventer din gennemgang.');}catch(e){toast(e.message);}};}
const cw=document.querySelector('#client-week');if(cw)cw.onchange=()=>{week=+cw.value;render();};document.querySelectorAll('[data-start]').forEach(el=>el.onclick=()=>{workout=el.dataset.start;render();window.scrollTo(0,0);});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action));}
function action(type){if(deleting)return;if(type==='new-intake'){createIntakeInvitation();return;}if(type==='refresh-intakes'){void loadIntakes();return;}if(type==='invite'){void inviteClient();return;}if(type==='refresh-invitations'){void loadInvitations();return;}if(type==='new-exercise'){editExercise();return;}if(type==='refresh-clients'){void loadClients();return;}const p=getP();if(type==='retry-save'){if(savePaused){toast('Genindlæs siden ved konflikt. Hold siden åben, hvis du har ændringer, som ikke er gemt.');return;}void flush();return;}if(type==='signout'){if(demo){location.assign('/');return;}if(dirty||saving){toast('Vent til alle ændringer er gemt, før du logger ud.');return;}void authClient.signOut().then(()=>location.assign('/'));return;}if(type==='previous'){collectForm();step=Math.max(0,step-1);render();}if(type==='approve'&&canApprove(p)){p.status='approved';p.approved_at=new Date().toISOString();save();render();toast('Godkendt. Du kan nu åbne brugervisningen.');}if(type==='client'&&p.status==='approved'){client=true;render();window.scrollTo(0,0);}if(type==='back-admin'){client=false;workout=null;render();}if(type==='print')window.print();if(type==='finish-workout'){workout=null;save();render();}if(type==='next-exercise'||type==='skip-exercise'){const s=p.sessions.find(s=>s.id===workout),key=p.id+':'+week+':'+s.id,progress=state.workouts[key];if(progress.index<0&&s.warmup_items?.length){progress.warmup_index=Math.min(progress.warmup_index||0,s.warmup_items.length-1)+1;if(progress.warmup_index>=s.warmup_items.length)progress.index=0;save();render();window.scrollTo(0,0);return;}const load=document.querySelector('#actual-load')?.value;if(load&&(!Number.isFinite(+load)||+load<0||+load>1000)){toast('Angiv en gyldig vægt mellem 0 og 1000 kg.');return;}progress.logs.push({index:progress.index,skipped:type==='skip-exercise',load_kg:load?+load:null,effort:document.querySelector('#actual-effort')?.value||null});progress.index++;if(progress.index>=s.items.length)progress.done=true;save();render();window.scrollTo(0,0);}if(type==='new-place'){modal('Opret træningssted',`<form id="place-form"><div class="field"><label>Navn<input name="name" maxlength="80" required placeholder="Fx: Hjemme hos personen"></label></div><div class="field"><label>Type<select name="type"><option>Hjemme</option><option>Center</option><option>Udendørs</option></select></label></div><button class="btn primary" type="submit">Opret træningssted</button></form>`);document.querySelector('#place-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),name=String(f.get('name')).trim();if(!name)return;const id=uuid();state.places.push({id,name,type:f.get('type'),note:'Vælg det udstyr, som faktisk er tilgængeligt.',inventory:[]});selectedPlace=id;save();document.querySelector('#modal').close();render();};}if(type==='command')command();}
function command(){const p=getP(),text=document.querySelector('#command').value.trim();if(!text)return;const draft=structuredClone(p),changes=[];
if(/løb.*cykel/i.test(text)){if(!p.inventory.includes('bike')){toast('Stedet har ingen motionscykel registreret.');return;}for(const s of draft.sessions)for(const x of s.items){const e=exercises.find(e=>e.id===x.exercise_id);if(e.category==='loeb'){changes.push(e.name_da+' → Motionscykel');x.exercise_id='E035';}}}else if(/fjern.*hop/i.test(text)){for(const s of draft.sessions)for(const x of s.items)if(x.exercise_id==='E044'){if(!available(exercises.find(e=>e.id==='E043'),p.inventory))continue;x.exercise_id='E043';changes.push('Burpee broad jump → Burpee med skridt');}}else{toast('Brug et af de to eksempler, eller rediger en øvelse direkte.');return;}
if(!changes.length){toast('Ingen øvelser i dette forløb matcher rettelsen.');return;}modal('Gennemgå dit ændringsforslag',`<p>${esc(text)}</p><ul>${changes.map(c=>`<li>${esc(c)}</li>`).join('')}</ul><p>Alternativet ændrer træningsformen og er ikke en præcis erstatning. Du skal gennemgå den nye kladde og godkende den igen.</p>`,`<button class="btn primary" id="apply-command">Anvend på ny kladde</button>`);document.querySelector('#apply-command').onclick=()=>{for(const s of draft.sessions){s.total_seconds=s.warmup_min*60+s.items.reduce((n,x)=>n+estimateSeconds(x),0);const err=validateSession(s,exercises,p.inventory);if(err.length){toast(err.join(' '));return;}}p.sessions=draft.sessions;document.querySelector('#modal').close();changed(p);toast('Forslaget er anvendt. Ny gennemgang kræves.');};}
window.addEventListener('hashchange',()=>{const next=location.hash.slice(1);if(nav.some(n=>n[0]===next)||next==='settings'){if(deleting)return;view=next;client=false;workout=null;render();if(view==='clients')void loadClients();if(view==='invitations')void loadInvitations();if(view==='intakes')void loadIntakes();}});
if(location.hash&&[...nav.map(n=>n[0]),'settings'].includes(location.hash.slice(1)))view=location.hash.slice(1);
render();if(view==='clients')void loadClients();if(view==='invitations')void loadInvitations();if(view==='intakes')void loadIntakes();

}
await start();
